class Solution {
public:
    int componentValue(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        long long S = 0;
        for (int x : nums) S += x;

        // Enumerate divisors of S in O(sqrt(S))
        vector<long long> divs;
        for (long long i = 1; i * i <= S; i++) {
            if (S % i == 0) {
                divs.push_back(i);
                if (i != S / i) divs.push_back(S / i);
            }
        }
        sort(divs.begin(), divs.end());

        // Build parent[] and order[] via iterative DFS (avoids stack overflow)
        vector<int> par(n, -1), order;
        order.reserve(n);
        vector<int> stk;
        stk.push_back(0);
        par[0] = -2; // mark root visited
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int v : adj[u]) {
                if (par[v] == -1) {
                    par[v] = u;
                    stk.push_back(v);
                }
            }
        }

        vector<long long> sum(n, 0);
        for (long long d : divs) {
            bool ok = true;
            int cuts = 0;
            for (int i = n - 1; i >= 0; i--) {
                int u = order[i];
                long long s = nums[u];
                for (int v : adj[u]) {
                    if (par[v] == u) {
                        s += sum[v];
                        if (s > d) {
                            ok = false;
                            break;
                        }
                    }
                }
                if (!ok) break;
                if (s == d) {
                    cuts++;
                    sum[u] = 0;
                } else {
                    sum[u] = s;
                }
            }
            if (ok && cuts == S / d) {
                return (int)(S / d - 1);
            }
        }
        return 0;
    }
};
